                            name: "OrgMateMarcoGeneralTitlebarUsesSystemFontMachine",
                            displayName: "\u0421\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u0439 \u0448\u0440\u0438\u0444\u0442 \u0432 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u0435 \u043E\u043A\u043D\u0430",
